function validate([s, k]) {
  if (typeof s !== 'string' || s.length < 1 || s.length > 100) return 's needs 1 to 100 characters.';
  if (!/^[a-z]+$/.test(s)) return 's may contain only lowercase letters.';
  if (!Number.isInteger(k) || k < 0 || k > 2000) return 'k is a whole number from 0 to 2000.';
  return null;
}

