function getSmallestString(s, k) {
  const chars = s.split('');
  let budget = k;

  for (let i = 0; i < chars.length && budget > 0; i++) {
    const offset = chars[i].charCodeAt(0) - 97;
    const toA = Math.min(offset, 26 - offset);
    if (toA <= budget) {
      chars[i] = 'a';
      budget -= toA;
    } else {
      chars[i] = String.fromCharCode(97 + offset - budget);
      budget = 0;
    }
  }
  return chars.join('');
}

