function getSmallestString(s, k) {
  // Fix positions left to right, trying letters from 'a' upward and taking the first one that fits.
  const gap = (a, b) => {
    let steps = 0;
    let c = a;
    while (c !== b) { c = (c + 1) % 26; steps++; }
    return Math.min(steps, 26 - steps);
  };
  let used = 0;
  let out = '';
  for (const ch of s) {
    const code = ch.charCodeAt(0) - 97;
    for (let letter = 0; letter < 26; letter++) {
      const cost = gap(code, letter);
      if (used + cost <= k) {
        used += cost;
        out += String.fromCharCode(97 + letter);
        break;
      }
    }
  }
  return out;
}

