function generate(rand, size) {
  const n = size === 'large' ? 100 : 1 + Math.floor(rand() * 6);
  let s = '';
  for (let i = 0; i < n; i++) s += String.fromCharCode(97 + Math.floor(rand() * 26));
  const k = size === 'large' ? Math.floor(rand() * rand() * 1500) : Math.floor(rand() * 30);
  return [s, k];
}
